import{_ as s,o as n,c as t,a2 as a}from"./chunks/framework.Lp3oD42U.js";const u=JSON.parse(`{"title":"Body measurements are stored metric and shown in the person's units","description":"","frontmatter":{"status":"accepted","date":"2026-11-01T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0017-body-measurements-are-stored-metric-and-shown-in-the-persons-units.md","filePath":"docs/adr/0017-body-measurements-are-stored-metric-and-shown-in-the-persons-units.md"}`),o={name:"docs/adr/0017-body-measurements-are-stored-metric-and-shown-in-the-persons-units.md"};function r(i,e,d,h,l,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="body-measurements-are-stored-metric-and-shown-in-the-person-s-units" tabindex="-1">Body measurements are stored metric and shown in the person&#39;s units <a class="header-anchor" href="#body-measurements-are-stored-metric-and-shown-in-the-person-s-units" aria-label="Permalink to &quot;Body measurements are stored metric and shown in the person&#39;s units&quot;">​</a></h1><p>Weight and height are logged as dated <strong>body measurements</strong>, stored in kilograms and centimetres whatever the person&#39;s <strong>unit system</strong>, and converted only when shown or typed. Each log entry is its own row and is added or corrected, never merged, so a chart is a plain read of the log and switching between metric and imperial changes nothing stored. The profile&#39;s other fields (birthdate, pronouns, sex assigned at birth) are single values, not a log; age is computed from the birthdate and never stored.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Conversion and rounding (kg to lb, cm to ft and in, with the half-inch the input allows) live in shared Kotlin with tests, like every decision about data; the apps only render.</li><li>Distances and speeds already follow the unit system the same way; this makes body measurements one more case, not a second mechanism.</li><li>A new SQLDelight migration adds the measurement table. No existing table changes, so existing phones lose nothing and no backward-compatibility code is needed.</li><li>Entries are append-only and per day, in the spirit of <a href="./0003-sessions-are-append-only-event-logs">ADR 0003</a> and <a href="./0006-sync-keeps-both-edits">ADR 0006</a>: when sync arrives, two phones&#39; entries both survive.</li><li>The profile stays on the phone, guest-only, until an account exists; nothing here sends it anywhere.</li></ul>',4)])])}const p=s(o,[["render",r]]);export{u as __pageData,p as default};
